insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"Do does home work_Do does home work_q01_do_does_s06","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\line_mssxn7k0.yaml","source_metadata":{}},{"key":"Do does home work_Do does home work_q01_do_does_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\line_mssxn7k0.yaml","source_metadata":{}},{"key":"Do does home work_Do does home work_q02_new_quest_s02_copy_copy_copy_copy","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\line_mssxn7k0.yaml","source_metadata":{}},{"key":"Do does home work_Do does home work_q02_new_quest_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\line_mssxn7k0.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"Do does home work_Do does home work_q01_do_does_s06","locale":"he","line_order":0,"content":"אוקיי, לא ציפיתי שתעברו את המבחן הזה בכזו קלות, ואו!","line_format":"plain_text"},{"dialogue_key":"Do does home work_Do does home work_q01_do_does_start","locale":"he","line_order":0,"content":"היי לכם, אחרי שלמדתם את כל הנושא כלכך טוב עם המדריכים שלכם, בא לי לבחון אתכם!","line_format":"plain_text"},{"dialogue_key":"Do does home work_Do does home work_q02_new_quest_s02_copy_copy_copy_copy","locale":"he","line_order":0,"content":"חזרתם! אני התרשמתי מאוד, קחו את זה  - מגיע לכם!","line_format":"plain_text"},{"dialogue_key":"Do does home work_Do does home work_q02_new_quest_start","locale":"he","line_order":0,"content":"החלטתם לעשות עוד מבחן? איזה כיף !","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
